'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{spawn}=require('node:child_process');
const root=path.resolve(__dirname,'..'),project=path.resolve(root,'../.rural-quiz-runtime/theme-content-review'),out=path.join(root,'qa/audio-natural-20261020',process.argv[2]||'native');fs.mkdirSync(out,{recursive:true});const events=[],checks=[];
async function call(tool,args=[]){return new Promise((resolve,reject)=>{const c=spawn('/usr/local/bin/wechatide',['-c','Codex',tool,'--project',project,...args]);let s='';c.stdout.on('data',b=>s+=b);c.stderr.on('data',b=>s+=b);const t=setTimeout(()=>{c.kill();reject(Error(tool+' timeout'));},40000);c.on('close',code=>{clearTimeout(t);let r;try{r=JSON.parse(s.slice(s.indexOf('{')));}catch{return reject(Error(s.slice(0,500)));}events.push({tool,args,result:r});fs.writeFileSync(path.join(out,'events.json'),JSON.stringify(events,null,2));if(code||!r.ok||r.result?.success===false)return reject(Error(r.message||r.result?.error));resolve(r.result);});});}
const load=(id,scene='home')=>call('automation_navigate',['--action','reLaunch','--url','/pages/game/index?theme='+id+'&review=1&controls=0&scenario='+scene]);
const tap=selector=>call('automation_element_action',['--action','tap','--selector',selector,'--wait-for-selector',selector]);
const trigger=selector=>call('automation_element_action',['--action','trigger','--selector',selector,'--type','action','--detail','{}','--wait-for-selector',selector]);
async function data(){return(await call('automation_page_action',['--action','getData','--wait-for-selector','.game-device'])).data;}
async function toggle(){await tap('#sound-settings');await tap('#sound-master');await tap('#sound-settings-done');}
async function record(theme,scene){const d=await data();assert.equal(d.soundErrorCount,0);const file=theme+'-'+scene+'.png';await call('simulator_screenshot',['--path',path.join(out,file),'--optimize','false','--wait-for-selector','#sound-settings']);checks.push({theme,scene,enabled:d.soundEnabled,musicPlaying:d.soundPlaying,effectPlays:d.soundEffectPlays,lastEffect:d.lastSoundEffect,errors:d.soundErrorCount,screenshot:file,passed:true});fs.writeFileSync(path.join(out,'checks.json'),JSON.stringify({scope:'Native WeChat devtools 390x844. Playback is confirmed by native InnerAudioContext onPlay callbacks; this is not a human listening or phone speaker verdict.',passed:true,checks},null,2));console.log('PASS '+theme+' '+scene);}
(async()=>{
 await data();
 for(const id of (process.argv[3]||'ecology,culture,red,industry').split(',')){
  await load(id);let d=await data();assert.equal(d.soundAvailable,true);assert.equal(d.soundPlaying,false);
  if(d.soundEnabled)await toggle();d=await data();assert.equal(d.soundEnabled,false);assert.equal(d.soundPlaying,false);
  await toggle();d=await data();assert.equal(d.soundEnabled,true);assert.equal(d.soundPlaying,true);await record(id,'home-audio-on');
  await tap('.chapter-mascot');d=await data();assert.equal(d.lastSoundEffect,'mascot');await record(id,'mascot-sound');
  const beforeRules=d.soundEffectPlays;await trigger('#footer-primary');d=await data();assert.equal(d.soundEffectPlays,beforeRules,'Ordinary level opening stays quiet');await trigger('#modal-primary');d=await data();assert.equal(d.route,'quiz');
  const catalog=require(path.join(project,'miniprogram/services-v4/catalog.js')),q=catalog.questions.find(q=>q.id===d.challenge.question.id);assert(q);
  const answer=d.options.findIndex(o=>o.text===q.options[q.answer]);assert(answer>=0,'Map the approved answer text to display options');await call('automation_element_action',['--action','scrollTo','--selector','.panel-body','--x','0','--y',answer>=2?'9999':'0']);await tap('.option[data-index="'+answer+'"]');d=await data();assert.equal(d.challenge.selected,answer,'Tap the visible answer before submitting');await trigger('#footer-primary');d=await data();assert.equal(d.challenge.status,'correct');assert.equal(d.lastSoundEffect,'correct');await record(id,'confirmed-correct');
  await load(id,'home&route=profile');d=await data();assert.equal(d.soundPlaying,false);let markup=await call('automation_element_action',['--action','outerWxml','--selector','.panel-body']);assert(!/减少动态效果|返回总入口/.test(JSON.stringify(markup)));await record(id,'profile-no-motion-card');
 }
 // Decode every packaged MP3 with native contexts. Silent volume avoids an overlapping test chorus.
 const fn='function(){const names=["ambient-piano","paper","wood","confirm-wood","piano-close","leaf-rustle"];return new Promise(resolve=>{const rows=[];function next(){const name=names.shift();if(!name){resolve(rows);return;}const c=wx.createInnerAudioContext();let ended=false;const finish=(ok,error)=>{if(ended)return;ended=true;clearTimeout(timer);c.stop();c.destroy();rows.push({name,ok,error});next();};const timer=setTimeout(()=>finish(false,"onPlay timeout"),5000);c.volume=0;c.obeyMuteSwitch=true;c.onPlay(()=>finish(true));c.onError(e=>finish(false,e.errMsg));c.src="/assets/audio/"+name+".mp3";c.play();}next();});}';let r=await call('automation_evaluate',['--fn-source',fn]);for(let i=0;i<4&&!Array.isArray(r);i++)r=r.result||r.data||r;assert(Array.isArray(r)&&r.length===6);assert(r.every(x=>x.ok));fs.writeFileSync(path.join(out,'native-decode.json'),JSON.stringify({passed:true,scope:'InnerAudioContext onPlay callback for each local MP3, not audible device acceptance.',files:r},null,2));console.log('PASS 6 native MP3 decode starts');
})().catch(e=>{fs.writeFileSync(path.join(out,'error.txt'),e.stack);fs.writeFileSync(path.join(out,'checks.json'),JSON.stringify({scope:'Partial native run; see error. Completed cases only.',passed:false,checks,error:e.message},null,2));console.error(e);process.exitCode=1;});
